diff --git a/packages/realtime/src/livekit-realtime-room.ts b/packages/realtime/src/livekit-realtime-room.ts
deleted file mode 100644
index adb93e91..00000000
--- a/packages/realtime/src/livekit-realtime-room.ts
+++ /dev/null
@@ -1,225 +0,0 @@
-import type {
-  ConnectError,
-  MediaError,
-  MediaTarget,
-  RealtimeRoom,
-  RoomCredentials,
-} from "@know-meet/application";
-import {
-  type ConnectionState,
-  err,
-  isInRoom,
-  meetingErrors,
-  ok,
-  type Result,
-  type TrackKind,
-} from "@know-meet/domain";
-import { ConnectionErrorReason, Room, type RoomOptions } from "livekit-client";
-import {
-  CONNECTED,
-  CONNECTING,
-  CONNECTION_LOST,
-  IDLE,
-  LEFT,
-  sameConnection,
-  toLiveConnection,
-} from "./connection-mapping.ts";
-import { type DiagnosticSink, ignoreDiagnostic } from "./diagnostics.ts";
-import { errorName, isTokenRejection, mapConnectError, mapMediaError } from "./error-mapping.ts";
-import { setLocalMediaEnabled } from "./livekit/media-control.ts";
-import { bindRoomEvents, type RoomEventHandlers } from "./livekit/room-events.ts";
-import { readRoomFacts } from "./livekit/room-facts.ts";
-import { createTrackResolver } from "./livekit/track-resolver.ts";
-import { createMediaBindings } from "./media-bindings.ts";
-import { createSnapshotStore } from "./snapshot-store.ts";
-
-export interface LiveKitRealtimeRoomOptions {
-  /**
-   * Let the SDK pause remote video whose element is hidden or small. Off by default: a
-   * two-person call gains little, and a hidden or background tab would stop video (README).
-   */
-  readonly adaptiveStream?: boolean;
-  /** Let the publisher pause simulcast layers nobody watches. On by default. */
-  readonly dynacast?: boolean;
-  /** Receives connection, failure and audio-playback events. Never receives a token. */
-  readonly onDiagnostic?: DiagnosticSink;
-}
-
-/** One SDK room from `connect` until it is left or lost. A new `connect` makes a new one. */
-interface Session {
-  readonly id: number;
-  readonly room: Room;
-  readonly unbind: () => void;
-}
-
-/** `ConnectionErrorReason.NotAllowed`: the server refused the token. */
-const TOKEN_REFUSED: number = ConnectionErrorReason.NotAllowed;
-
-/**
- * The RealtimeRoom port over livekit-client. Nothing it returns names an SDK type. It opens
- * no connection until `connect`, so a refused token request never reaches the media server.
- */
-export function createLiveKitRealtimeRoom(options: LiveKitRealtimeRoomOptions = {}): RealtimeRoom {
-  const report = options.onDiagnostic ?? ignoreDiagnostic;
-  const roomOptions: RoomOptions = {
-    adaptiveStream: options.adaptiveStream ?? false,
-    dynacast: options.dynacast ?? true,
-    webAudioMix: false,
-  };
-  const store = createSnapshotStore();
-  const bindings = createMediaBindings();
-  let session: Session | null = null;
-  let pendingConnect: number | null = null;
-  let connection: ConnectionState = IDLE;
-  let sessionCount = 0;
-  let refreshQueued = false;
-
-  const isCurrent = (id: number): boolean => session !== null && session.id === id;
-
-  /** Re-reads the SDK, publishes a new snapshot if anything changed, and re-binds media. */
-  const refresh = (): void => {
-    const room = session?.room ?? null;
-    store.update(readRoomFacts(room, connection));
-    bindings.reconcile(createTrackResolver(room));
-  };
-
-  /**
-   * SDK events fire mid-update (for example `TrackUnsubscribed` before the publication drops
-   * its track), so participant changes are read one microtask later, batched.
-   */
-  const scheduleRefresh = (): void => {
-    if (refreshQueued) return;
-    refreshQueued = true;
-    queueMicrotask(() => {
-      refreshQueued = false;
-      refresh();
-    });
-  };
-
-  const setConnection = (next: ConnectionState): void => {
-    if (!sameConnection(connection, next)) report({ type: "connection-changed", connection: next });
-    connection = next;
-    refresh();
-  };
-
-  /** Removes our listeners, then disposes the room: disconnect, stop local tracks, drop globals. */
-  const release = async (ended: Session): Promise<void> => {
-    ended.unbind();
-    try {
-      await ended.room.dispose();
-    } catch (error) {
-      report({ type: "teardown-failed", errorName: errorName(error) });
-    }
-  };
-
-  /** The SDK gave up reconnecting, or the server ended the session. The guest did not leave. */
-  const onSessionEnded = (id: number): void => {
-    if (session === null || !isCurrent(id) || pendingConnect === id) return;
-    const lost = session;
-    session = null;
-    setConnection(CONNECTION_LOST);
-    void release(lost);
-  };
-
-  const handlersFor = (id: number): RoomEventHandlers => ({
-    onChange: () => {
-      if (isCurrent(id)) scheduleRefresh();
-    },
-    onConnectionState: (sdkState) => {
-      const next = toLiveConnection(sdkState);
-      if (next !== null && isCurrent(id)) setConnection(next);
-    },
-    onDisconnected: () => onSessionEnded(id),
-    onAudioPlayback: (playing) => report({ type: "audio-playback", playing }),
-  });
-
-  const attempt = async (
-    room: Room,
-    credentials: RoomCredentials,
-  ): Promise<Result<void, unknown>> => {
-    try {
-      await room.connect(credentials.url, credentials.token);
-      return ok(undefined);
-    } catch (error) {
-      return err(error);
-    }
-  };
-
-  const failConnect = async (error: unknown): Promise<Result<void, ConnectError>> => {
-    const tokenRejected = isTokenRejection(error, TOKEN_REFUSED);
-    report({ type: "connect-failed", errorName: errorName(error), tokenRejected });
-    const failed = session;
-    session = null;
-    setConnection(IDLE);
-    if (failed !== null) await release(failed);
-    // One attempt only: a refused token is not retried, and neither is an unreachable server.
-    return err(mapConnectError(error, TOKEN_REFUSED));
-  };
-
-  /**
-   * Playback of remote audio needs a user gesture. Join starts from a click, so this runs
-   * close to it; if the browser still blocks audio, `audio-playback` reports `playing: false`
-   * and remote audio stays silent until the page calls startAudio from another gesture
-   * (not exposed by the port yet; see README).
-   */
-  const startAudio = (room: Room): void => {
-    void room.startAudio().catch(() => report({ type: "audio-playback", playing: false }));
-  };
-
-  const connect = async (credentials: RoomCredentials): Promise<Result<void, ConnectError>> => {
-    if (session !== null) {
-      const previous = session;
-      session = null;
-      await release(previous);
-    }
-    sessionCount += 1;
-    const id = sessionCount;
-    const room = new Room(roomOptions);
-    session = { id, room, unbind: bindRoomEvents(room, handlersFor(id)) };
-    pendingConnect = id;
-    setConnection(CONNECTING);
-    const outcome = await attempt(room, credentials);
-    if (pendingConnect === id) pendingConnect = null;
-    // `disconnect` ran while connecting: it already tore the room down and reported `left`.
-    if (!isCurrent(id)) return err(meetingErrors.connectionLost());
-    if (!outcome.ok) return failConnect(outcome.error);
-    setConnection(CONNECTED);
-    startAudio(room);
-    return ok(undefined);
-  };
-
-  const disconnect = async (): Promise<void> => {
-    const ending = session;
-    session = null;
-    if (ending !== null) await release(ending);
-    setConnection(LEFT);
-  };
-
-  const setMediaEnabled = async (
-    kind: TrackKind,
-    enabled: boolean,
-  ): Promise<Result<void, MediaError>> => {
-    const active = session;
-    if (active === null || !isInRoom(connection)) return err(meetingErrors.connectionLost());
-    try {
-      await setLocalMediaEnabled(active.room, kind, enabled);
-    } catch (error) {
-      report({ type: "media-failed", kind, errorName: errorName(error) });
-      if (session === active) refresh();
-      return err(mapMediaError(error, kind));
-    }
-    if (session !== active) return err(meetingErrors.connectionLost());
-    refresh();
-    return ok(undefined);
-  };
-
-  return {
-    connect,
-    disconnect,
-    setMediaEnabled,
-    getSnapshot: store.get,
-    subscribe: store.subscribe,
-    attachMedia: (target: MediaTarget, element: HTMLMediaElement) =>
-      bindings.bind(target, element, createTrackResolver(session?.room ?? null)),
-  };
-}
diff --git a/packages/realtime/src/livekit/media-control.ts b/packages/realtime/src/livekit/media-control.ts
deleted file mode 100644
index 2584c0de..00000000
--- a/packages/realtime/src/livekit/media-control.ts
+++ /dev/null
@@ -1,21 +0,0 @@
-import type { TrackKind } from "@know-meet/domain";
-import type { Room } from "livekit-client";
-
-/**
- * Turns the local microphone or camera on or off. The first enable asks the browser for the
- * device and publishes the track; later calls mute or unmute it. A refused device rejects with
- * the getUserMedia error (for example `NotAllowedError`) and leaves the room connected.
- * Muting the camera stops the device, so the camera light goes off; muting the microphone
- * keeps the device open (SDK default `stopMicTrackOnMute: false`).
- */
-export async function setLocalMediaEnabled(
-  room: Room,
-  kind: TrackKind,
-  enabled: boolean,
-): Promise<void> {
-  if (kind === "microphone") {
-    await room.localParticipant.setMicrophoneEnabled(enabled);
-    return;
-  }
-  await room.localParticipant.setCameraEnabled(enabled);
-}
diff --git a/packages/realtime/src/livekit/room-events.ts b/packages/realtime/src/livekit/room-events.ts
deleted file mode 100644
index fdcdfa5a..00000000
--- a/packages/realtime/src/livekit/room-events.ts
+++ /dev/null
@@ -1,48 +0,0 @@
-import { type Room, RoomEvent } from "livekit-client";
-
-export interface RoomEventHandlers {
-  /** Participants, publications, subscriptions or mute state changed. */
-  readonly onChange: () => void;
-  /** The SDK's connection state as its string value, e.g. `reconnecting`. */
-  readonly onConnectionState: (sdkState: string) => void;
-  /** The SDK ended the session (it emits this after its own teardown). */
-  readonly onDisconnected: () => void;
-  readonly onAudioPlayback: (playing: boolean) => void;
-}
-
-/** Registers the handlers on `room` and returns the function that removes every one of them. */
-export function bindRoomEvents(room: Room, handlers: RoomEventHandlers): () => void {
-  const { onChange, onConnectionState, onDisconnected, onAudioPlayback } = handlers;
-  room.on(RoomEvent.ConnectionStateChanged, onConnectionState);
-  room.on(RoomEvent.Disconnected, onDisconnected);
-  room.on(RoomEvent.AudioPlaybackStatusChanged, onAudioPlayback);
-  room.on(RoomEvent.ParticipantConnected, onChange);
-  room.on(RoomEvent.ParticipantDisconnected, onChange);
-  room.on(RoomEvent.ParticipantNameChanged, onChange);
-  room.on(RoomEvent.TrackPublished, onChange);
-  room.on(RoomEvent.TrackUnpublished, onChange);
-  room.on(RoomEvent.TrackSubscribed, onChange);
-  room.on(RoomEvent.TrackUnsubscribed, onChange);
-  room.on(RoomEvent.TrackSubscriptionStatusChanged, onChange);
-  room.on(RoomEvent.TrackMuted, onChange);
-  room.on(RoomEvent.TrackUnmuted, onChange);
-  room.on(RoomEvent.LocalTrackPublished, onChange);
-  room.on(RoomEvent.LocalTrackUnpublished, onChange);
-  return () => {
-    room.off(RoomEvent.ConnectionStateChanged, onConnectionState);
-    room.off(RoomEvent.Disconnected, onDisconnected);
-    room.off(RoomEvent.AudioPlaybackStatusChanged, onAudioPlayback);
-    room.off(RoomEvent.ParticipantConnected, onChange);
-    room.off(RoomEvent.ParticipantDisconnected, onChange);
-    room.off(RoomEvent.ParticipantNameChanged, onChange);
-    room.off(RoomEvent.TrackPublished, onChange);
-    room.off(RoomEvent.TrackUnpublished, onChange);
-    room.off(RoomEvent.TrackSubscribed, onChange);
-    room.off(RoomEvent.TrackUnsubscribed, onChange);
-    room.off(RoomEvent.TrackSubscriptionStatusChanged, onChange);
-    room.off(RoomEvent.TrackMuted, onChange);
-    room.off(RoomEvent.TrackUnmuted, onChange);
-    room.off(RoomEvent.LocalTrackPublished, onChange);
-    room.off(RoomEvent.LocalTrackUnpublished, onChange);
-  };
-}
diff --git a/packages/realtime/src/livekit/room-facts.ts b/packages/realtime/src/livekit/room-facts.ts
deleted file mode 100644
index 54fb9fc9..00000000
--- a/packages/realtime/src/livekit/room-facts.ts
+++ /dev/null
@@ -1,35 +0,0 @@
-import type { ConnectionState } from "@know-meet/domain";
-import { type Participant, type Room, Track } from "livekit-client";
-import {
-  type ParticipantFacts,
-  type RoomFacts,
-  type TrackFacts,
-  UNPUBLISHED,
-} from "../snapshot-mapping.ts";
-
-/** Reads the SDK room into plain facts. `room` is null before connecting and after leaving. */
-export function readRoomFacts(room: Room | null, connection: ConnectionState): RoomFacts {
-  if (room === null) return { connection, local: null, remotes: [] };
-  return {
-    connection,
-    local: readParticipant(room.localParticipant),
-    // `remoteParticipants` is a Map keyed by identity; its iteration order is insertion order.
-    remotes: [...room.remoteParticipants.values()].map(readParticipant),
-  };
-}
-
-function readParticipant(participant: Participant): ParticipantFacts {
-  return {
-    identity: participant.identity,
-    name: participant.name,
-    microphone: readTrack(participant, Track.Source.Microphone),
-    camera: readTrack(participant, Track.Source.Camera),
-  };
-}
-
-function readTrack(participant: Participant, source: Track.Source): TrackFacts {
-  const publication = participant.getTrackPublication(source);
-  if (publication === undefined) return UNPUBLISHED;
-  // Remote publications override `isSubscribed` (false while unsubscribed or not allowed).
-  return { muted: publication.isMuted, subscribed: publication.isSubscribed };
-}
diff --git a/packages/realtime/src/livekit/track-resolver.ts b/packages/realtime/src/livekit/track-resolver.ts
deleted file mode 100644
index 8b76160b..00000000
--- a/packages/realtime/src/livekit/track-resolver.ts
+++ /dev/null
@@ -1,30 +0,0 @@
-import type { MediaTarget } from "@know-meet/application";
-import { type Room, Track } from "livekit-client";
-import type { AttachableTrack, TrackResolver } from "../media-bindings.ts";
-
-/**
- * Which SDK track a target plays in `room` right now.
- * - Local camera: the published camera track (kept while muted; the SDK restarts it in place).
- * - Local microphone: never, so a guest does not hear themselves.
- * - Remote camera or microphone: the track only while subscribed.
- */
-export function createTrackResolver(room: Room | null): TrackResolver {
-  return (target) => {
-    if (room === null) return null;
-    if (target.identity === room.localParticipant.identity) return localTrack(room, target);
-    const publication = room.remoteParticipants
-      .get(target.identity)
-      ?.getTrackPublication(sourceOf(target));
-    if (publication === undefined || !publication.isSubscribed) return null;
-    return publication.track ?? null;
-  };
-}
-
-function localTrack(room: Room, target: MediaTarget): AttachableTrack | null {
-  if (target.kind === "microphone") return null;
-  return room.localParticipant.getTrackPublication(Track.Source.Camera)?.track ?? null;
-}
-
-function sourceOf(target: MediaTarget): Track.Source {
-  return target.kind === "camera" ? Track.Source.Camera : Track.Source.Microphone;
-}
diff --git a/packages/realtime/src/realtime-room/application/diagnostics.ts b/packages/realtime/src/realtime-room/application/diagnostics.ts
new file mode 100644
index 00000000..b7c36db3
--- /dev/null
+++ b/packages/realtime/src/realtime-room/application/diagnostics.ts
@@ -0,0 +1,36 @@
+import type { ConnectionState, DeviceKind, TrackKind } from "@know-meet/domain";
+
+/** Which text channel a message event is about. */
+export type MessageChannel = "chat" | "consent";
+
+/** Why a received text stream was not delivered. */
+export type DropReason = "too-large" | "unreadable" | "malformed";
+
+/**
+ * What the adapter reports for debugging a meeting. Carries error names only, never messages,
+ * tokens, URLs, message text or device labels, so a sink may forward it to logs.
+ */
+export type RealtimeDiagnostic =
+  | { readonly type: "connection-changed"; readonly connection: ConnectionState }
+  | { readonly type: "connect-failed"; readonly errorName: string; readonly tokenRejected: boolean }
+  | { readonly type: "media-failed"; readonly kind: TrackKind; readonly errorName: string }
+  /** `playing: false` means the browser blocked audio until a user gesture calls startAudio. */
+  | { readonly type: "audio-playback"; readonly playing: boolean }
+  | { readonly type: "teardown-failed"; readonly errorName: string }
+  | { readonly type: "screen-share-failed"; readonly errorName: string }
+  | {
+      readonly type: "message-send-failed";
+      readonly channel: MessageChannel;
+      readonly errorName: string;
+    }
+  | {
+      readonly type: "message-dropped";
+      readonly channel: MessageChannel;
+      readonly reason: DropReason;
+    }
+  | { readonly type: "device-switch-failed"; readonly kind: DeviceKind; readonly errorName: string }
+  | { readonly type: "background-effect-failed"; readonly errorName: string };
+
+export type DiagnosticSink = (diagnostic: RealtimeDiagnostic) => void;
+
+export const ignoreDiagnostic: DiagnosticSink = () => {};
diff --git a/packages/realtime/src/realtime-room/application/media-bindings.ts b/packages/realtime/src/realtime-room/application/media-bindings.ts
new file mode 100644
index 00000000..3603db07
--- /dev/null
+++ b/packages/realtime/src/realtime-room/application/media-bindings.ts
@@ -0,0 +1,64 @@
+import type { MediaTarget } from "@know-meet/application";
+
+/** The two calls the registry needs from a media track. The SDK's `Track` satisfies it. */
+export interface AttachableTrack {
+  attach(element: HTMLMediaElement): unknown;
+  detach(element: HTMLMediaElement): unknown;
+}
+
+/** The track a target should play right now, or null when there is none to play. */
+export type TrackResolver = (target: MediaTarget) => AttachableTrack | null;
+
+/**
+ * Element bindings that outlive any one track. Each binding remembers which track it attached;
+ * `reconcile` asks the resolver again and, where the answer changed, detaches the old track and
+ * attaches the new one. That is how a binding survives unsubscribe and resubscribe (a new track
+ * object), reconnection, and a `bind` that happens before the track exists.
+ */
+export interface MediaBindings {
+  /** Binds and attaches at once if a track exists. The returned function detaches; it is idempotent. */
+  bind(target: MediaTarget, element: HTMLMediaElement, resolve: TrackResolver): () => void;
+  reconcile(resolve: TrackResolver): void;
+  /** Live bindings, for tests and diagnostics. */
+  count(): number;
+}
+
+interface Binding {
+  readonly target: MediaTarget;
+  readonly element: HTMLMediaElement;
+}
+
+export function createMediaBindings(): MediaBindings {
+  const attached = new Map<Binding, AttachableTrack | null>();
+
+  const update = (
+    binding: Binding,
+    current: AttachableTrack | null,
+    next: AttachableTrack | null,
+  ) => {
+    if (next === current) return;
+    if (current !== null) current.detach(binding.element);
+    if (next !== null) next.attach(binding.element);
+    attached.set(binding, next);
+  };
+
+  return {
+    bind: (target, element, resolve) => {
+      const binding: Binding = { target, element };
+      attached.set(binding, null);
+      update(binding, null, resolve(target));
+      return () => {
+        if (!attached.has(binding)) return;
+        const current = attached.get(binding) ?? null;
+        attached.delete(binding);
+        if (current !== null) current.detach(element);
+      };
+    },
+    reconcile: (resolve) => {
+      for (const [binding, current] of [...attached]) {
+        update(binding, current, resolve(binding.target));
+      }
+    },
+    count: () => attached.size,
+  };
+}
diff --git a/packages/realtime/src/realtime-room/application/snapshot-store.ts b/packages/realtime/src/realtime-room/application/snapshot-store.ts
new file mode 100644
index 00000000..8f73b7a5
--- /dev/null
+++ b/packages/realtime/src/realtime-room/application/snapshot-store.ts
@@ -0,0 +1,33 @@
+import type { RoomSnapshot } from "@know-meet/application";
+import { INITIAL_SNAPSHOT, nextSnapshot, type RoomFacts } from "../domain/snapshot-mapping.ts";
+
+/** Holds the current snapshot and notifies listeners only when it is replaced. */
+export interface SnapshotStore {
+  get(): RoomSnapshot;
+  /** Applies fresh facts. Returns true when the snapshot changed (listeners were notified). */
+  update(facts: RoomFacts): boolean;
+  subscribe(listener: () => void): () => void;
+}
+
+export function createSnapshotStore(initial: RoomSnapshot = INITIAL_SNAPSHOT): SnapshotStore {
+  let snapshot = initial;
+  const listeners = new Set<() => void>();
+
+  return {
+    get: () => snapshot,
+    update: (facts) => {
+      const next = nextSnapshot(snapshot, facts);
+      if (next === snapshot) return false;
+      snapshot = next;
+      // A copy, so a listener may unsubscribe while being notified.
+      for (const listener of [...listeners]) listener();
+      return true;
+    },
+    subscribe: (listener) => {
+      listeners.add(listener);
+      return () => {
+        listeners.delete(listener);
+      };
+    },
+  };
+}
diff --git a/packages/realtime/src/realtime-room/domain/background-effect-plan.ts b/packages/realtime/src/realtime-room/domain/background-effect-plan.ts
new file mode 100644
index 00000000..5947f02b
--- /dev/null
+++ b/packages/realtime/src/realtime-room/domain/background-effect-plan.ts
@@ -0,0 +1,44 @@
+import type { BackgroundEffect, BackgroundEffectStatus } from "@know-meet/domain";
+
+/** The published camera as the effect controller sees it. */
+export type CameraState = "none" | "off" | "on";
+
+/** What the controller knows about the camera track it looks at now. */
+export interface EffectFacts {
+  readonly requested: BackgroundEffect;
+  readonly camera: CameraState;
+  /** This track carries a processor the hook set, for the requested effect. */
+  readonly appliedHere: boolean;
+  /** The hook set a processor on this track (for any effect) that is still there. */
+  readonly processorHere: boolean;
+  /** Applying the requested effect to this track already failed. */
+  readonly failedHere: boolean;
+}
+
+/**
+ * The next step, and the status to show while it runs or once it is done.
+ * - `remove`: take our processor off this track.
+ * - `apply`: put the requested effect on this track.
+ * - `none`: nothing to do.
+ */
+export interface EffectPlan {
+  readonly action: "remove" | "apply" | "none";
+  readonly status: BackgroundEffectStatus;
+}
+
+/**
+ * Keeps the requested effect true on whatever camera track is published. A muted camera keeps
+ * its processor (the SDK restarts it with the device), so it is only `pending` there. A track
+ * that lost its processor, or a new track (republished after a reconnect), gets it again. A
+ * failure is not retried on the same track until the request changes, so a broken processor
+ * cannot loop.
+ */
+export function planBackgroundEffect(facts: EffectFacts): EffectPlan {
+  if (facts.requested.kind === "none") {
+    return { action: facts.processorHere ? "remove" : "none", status: "idle" };
+  }
+  if (facts.camera !== "on") return { action: "none", status: "pending" };
+  if (facts.appliedHere) return { action: "none", status: "active" };
+  if (facts.failedHere) return { action: "none", status: "failed" };
+  return { action: "apply", status: "applying" };
+}
diff --git a/packages/realtime/src/realtime-room/domain/connection-mapping.ts b/packages/realtime/src/realtime-room/domain/connection-mapping.ts
new file mode 100644
index 00000000..1659c69b
--- /dev/null
+++ b/packages/realtime/src/realtime-room/domain/connection-mapping.ts
@@ -0,0 +1,39 @@
+import type { ConnectionState } from "@know-meet/domain";
+
+export const IDLE: ConnectionState = { status: "idle" };
+export const CONNECTING: ConnectionState = { status: "connecting" };
+export const CONNECTED: ConnectionState = { status: "connected" };
+export const RECONNECTING: ConnectionState = { status: "reconnecting" };
+export const LEFT: ConnectionState = { status: "disconnected", reason: "left" };
+export const CONNECTION_LOST: ConnectionState = {
+  status: "disconnected",
+  reason: "connection-lost",
+};
+
+/**
+ * Maps the media SDK's connection state (its string values: `connecting`, `connected`,
+ * `reconnecting`, `signalReconnecting`, `disconnected`) to the domain state. Returns null for
+ * `disconnected` and anything unknown: why a session ended is known only to the adapter (the
+ * guest left, or the link was lost), so the adapter sets that state itself.
+ */
+export function toLiveConnection(sdkState: string): ConnectionState | null {
+  switch (sdkState) {
+    case "connecting":
+      return CONNECTING;
+    case "connected":
+      return CONNECTED;
+    case "reconnecting":
+    case "signalReconnecting":
+      return RECONNECTING;
+    default:
+      return null;
+  }
+}
+
+export function sameConnection(a: ConnectionState, b: ConnectionState): boolean {
+  return a.status === b.status && reasonOf(a) === reasonOf(b);
+}
+
+function reasonOf(state: ConnectionState): string | null {
+  return state.status === "disconnected" ? state.reason : null;
+}
diff --git a/packages/realtime/src/realtime-room/domain/device-mapping.ts b/packages/realtime/src/realtime-room/domain/device-mapping.ts
new file mode 100644
index 00000000..f4af26d9
--- /dev/null
+++ b/packages/realtime/src/realtime-room/domain/device-mapping.ts
@@ -0,0 +1,95 @@
+import {
+  type ActiveDevices,
+  type DeviceChoice,
+  type DeviceKind,
+  type MediaDevice,
+  toDeviceId,
+} from "@know-meet/domain";
+
+/** The fields read from a browser `MediaDeviceInfo`. */
+export interface DeviceInfoFacts {
+  readonly kind: string;
+  readonly deviceId: string;
+  readonly label: string;
+}
+
+export const NO_DEVICES: readonly MediaDevice[] = [];
+
+/** The browser's `MediaDeviceKind` for one of ours. */
+export function browserKindOf(kind: DeviceKind): MediaDeviceKind {
+  switch (kind) {
+    case "microphone":
+      return "audioinput";
+    case "camera":
+      return "videoinput";
+    case "speaker":
+      return "audiooutput";
+  }
+}
+
+function deviceKindOf(browserKind: string): DeviceKind | null {
+  switch (browserKind) {
+    case "audioinput":
+      return "microphone";
+    case "videoinput":
+      return "camera";
+    case "audiooutput":
+      return "speaker";
+    default:
+      return null;
+  }
+}
+
+/**
+ * The browser list as domain devices, in browser order. Entries without an id (what a browser
+ * reports before the site has permission) are left out. The browser lists the system default
+ * of each kind first (Media Capture spec), so the first entry per kind is `isDefault`.
+ */
+export function toMediaDevices(infos: readonly DeviceInfoFacts[]): readonly MediaDevice[] {
+  const seen = new Set<DeviceKind>();
+  const devices: MediaDevice[] = [];
+  for (const info of infos) {
+    const kind = deviceKindOf(info.kind);
+    const id = toDeviceId(info.deviceId);
+    if (kind === null || id === null) continue;
+    devices.push({ kind, id, label: info.label, isDefault: !seen.has(kind) });
+    seen.add(kind);
+  }
+  return devices.length === 0 ? NO_DEVICES : devices;
+}
+
+export function sameDevices(a: readonly MediaDevice[], b: readonly MediaDevice[]): boolean {
+  if (a.length !== b.length) return false;
+  return a.every((device, index) => {
+    const other = b[index];
+    return (
+      other !== undefined &&
+      device.kind === other.kind &&
+      device.id === other.id &&
+      device.label === other.label &&
+      device.isDefault === other.isDefault
+    );
+  });
+}
+
+export function sameActiveDevices(a: ActiveDevices, b: ActiveDevices): boolean {
+  return a.microphone === b.microphone && a.camera === b.camera && a.speaker === b.speaker;
+}
+
+/** The lobby choice as the devices requested for a new session; the speaker stays as it was. */
+export function requestedFromChoice(choice: DeviceChoice, previous: ActiveDevices): ActiveDevices {
+  return { microphone: choice.microphone, camera: choice.camera, speaker: previous.speaker };
+}
+
+/**
+ * What each kind uses now: the device the SDK reports in use, else the one requested (or
+ * `null`, the system default). `inUse` returns the SDK's id for a browser kind, if any.
+ */
+export function activeDevicesFrom(
+  inUse: (kind: MediaDeviceKind) => string | undefined,
+  requested: ActiveDevices,
+): ActiveDevices {
+  const read = (kind: DeviceKind) =>
+    toDeviceId(inUse(browserKindOf(kind)) ?? "") ?? requested[kind];
+  return { microphone: read("microphone"), camera: read("camera"), speaker: read("speaker") };
+}
diff --git a/packages/realtime/src/realtime-room/domain/error-mapping.ts b/packages/realtime/src/realtime-room/domain/error-mapping.ts
new file mode 100644
index 00000000..9c36bd08
--- /dev/null
+++ b/packages/realtime/src/realtime-room/domain/error-mapping.ts
@@ -0,0 +1,121 @@
+import type {
+  ConnectError,
+  DeviceError,
+  MediaError,
+  ScreenShareError,
+} from "@know-meet/application";
+import {
+  conferencingErrors,
+  type DeviceKind,
+  meetingErrors,
+  type TrackKind,
+} from "@know-meet/domain";
+
+/**
+ * Names of errors that mean "this device could not be used": getUserMedia DOMExceptions (the
+ * same names the SDK's `MediaDeviceFailure.getFailure` classifies) plus the SDK's own
+ * `DeviceUnsupportedError` (no `navigator.mediaDevices`, for example an insecure origin).
+ * The port has one code for all of them, permission-denied; see README "Not handled".
+ */
+const DEVICE_ERROR_NAMES: ReadonlySet<string> = new Set([
+  "NotAllowedError",
+  "PermissionDeniedError",
+  "SecurityError",
+  "NotFoundError",
+  "DevicesNotFoundError",
+  "NotReadableError",
+  "TrackStartError",
+  "OverconstrainedError",
+  "DeviceUnsupportedError",
+]);
+
+/** The error's `name`, or "unknown". Never the message: it may echo server text. */
+export function errorName(error: unknown): string {
+  if (typeof error === "object" && error !== null && "name" in error) {
+    if (typeof error.name === "string") return error.name;
+  }
+  return "unknown";
+}
+
+/**
+ * True when the media server refused the access token: an SDK `ConnectionError` whose
+ * `reason` is `ConnectionErrorReason.NotAllowed` (401 rejected or expired token, 403, or 404
+ * unknown room). `notAllowedReason` is that enum value, passed in so this file stays free of
+ * the SDK.
+ */
+export function isTokenRejection(error: unknown, notAllowedReason: number): boolean {
+  if (errorName(error) !== "ConnectionError") return false;
+  if (typeof error !== "object" || error === null || !("reason" in error)) return false;
+  return error.reason === notAllowedReason;
+}
+
+/** Token refused: forbidden, and the caller does not retry. Anything else: connection-lost. */
+export function mapConnectError(error: unknown, notAllowedReason: number): ConnectError {
+  return isTokenRejection(error, notAllowedReason)
+    ? meetingErrors.forbidden()
+    : meetingErrors.connectionLost();
+}
+
+/**
+ * A device the browser refused or could not open: permission-denied for that device, and the
+ * guest stays in the room. Anything else (publishing failed, the room went away): connection-lost.
+ */
+export function mapMediaError(error: unknown, kind: TrackKind): MediaError {
+  return DEVICE_ERROR_NAMES.has(errorName(error))
+    ? meetingErrors.permissionDenied(kind)
+    : meetingErrors.connectionLost();
+}
+
+/**
+ * What `getDisplayMedia` throws when no share begins: the picker was closed (`NotAllowedError`
+ * in Chromium and Firefox, `AbortError` in some versions), the call was not in a user gesture
+ * (`InvalidStateError` in WebKit), nothing could be captured, or the stream had no video
+ * (the SDK's `TrackInvalidError`).
+ */
+const SHARE_REFUSAL_NAMES: ReadonlySet<string> = new Set([
+  "NotAllowedError",
+  "PermissionDeniedError",
+  "AbortError",
+  "InvalidStateError",
+  "NotFoundError",
+  "NotReadableError",
+  "SecurityError",
+  "OverconstrainedError",
+  "TypeError",
+  "TrackInvalidError",
+]);
+
+/**
+ * No `getDisplayMedia` (the SDK's `DeviceUnsupportedError`): unsupported. A refused or closed
+ * picker: share-not-started. Anything else (publishing failed, the room went away):
+ * connection-lost.
+ */
+export function mapScreenShareError(error: unknown): ScreenShareError {
+  const name = errorName(error);
+  if (name === "DeviceUnsupportedError") return conferencingErrors.unsupported("screenShare");
+  return SHARE_REFUSAL_NAMES.has(name)
+    ? conferencingErrors.shareNotStarted()
+    : meetingErrors.connectionLost();
+}
+
+/** The chosen device is not connected (any more). */
+const DEVICE_GONE_NAMES: ReadonlySet<string> = new Set([
+  "OverconstrainedError",
+  "NotFoundError",
+  "DevicesNotFoundError",
+]);
+
+/**
+ * A failed device switch. Gone: device-not-found. A refused or unusable input:
+ * permission-denied for that input. A speaker the browser would not switch to (no
+ * `setSinkId`, or `NotAllowedError` for an output the page may not use): unsupported, since
+ * the port has no permission code for speakers. Anything else for an input: connection-lost.
+ */
+export function mapDeviceSwitchError(error: unknown, kind: DeviceKind): DeviceError {
+  const name = errorName(error);
+  if (DEVICE_GONE_NAMES.has(name)) return conferencingErrors.deviceNotFound(kind);
+  if (kind === "speaker") return conferencingErrors.unsupported("speakerSelection");
+  return DEVICE_ERROR_NAMES.has(name)
+    ? meetingErrors.permissionDenied(kind)
+    : meetingErrors.connectionLost();
+}
diff --git a/packages/realtime/src/realtime-room/domain/participant-mapping.ts b/packages/realtime/src/realtime-room/domain/participant-mapping.ts
new file mode 100644
index 00000000..19550977
--- /dev/null
+++ b/packages/realtime/src/realtime-room/domain/participant-mapping.ts
@@ -0,0 +1,111 @@
+import {
+  type LocalParticipant,
+  type RemoteParticipant,
+  toParticipantIdentity,
+} from "@know-meet/domain";
+
+/**
+ * Plain facts read from the media SDK at one moment. The SDK reader produces them; nothing
+ * here knows the SDK, so the mapping is testable with hand-made values.
+ */
+export interface TrackFacts {
+  /** True when nothing is sent: muted, never published or unpublished. */
+  readonly muted: boolean;
+  /** True when this client receives the track. Ignored for the local participant. */
+  readonly subscribed: boolean;
+}
+
+export interface ParticipantFacts {
+  readonly identity: string;
+  /** The name from the access token; empty or missing falls back to the identity. */
+  readonly name: string | undefined;
+  readonly microphone: TrackFacts;
+  readonly camera: TrackFacts;
+}
+
+export const UNPUBLISHED: TrackFacts = { muted: true, subscribed: false };
+
+export const NO_REMOTES: readonly RemoteParticipant[] = [];
+
+export function nextLocal(
+  previous: LocalParticipant | null,
+  facts: ParticipantFacts,
+): LocalParticipant {
+  const local = toLocal(facts);
+  return previous !== null && sameLocal(previous, local) ? previous : local;
+}
+
+/** Remotes keep the order they first appeared in; newcomers go to the end. */
+export function nextRemotes(
+  previous: readonly RemoteParticipant[],
+  facts: readonly ParticipantFacts[],
+): readonly RemoteParticipant[] {
+  const byIdentity = new Map<string, ParticipantFacts>(facts.map((fact) => [fact.identity, fact]));
+  const known = new Set<string>(previous.map((entry) => entry.identity));
+  const ordered: RemoteParticipant[] = [];
+  for (const prior of previous) {
+    const fact = byIdentity.get(prior.identity);
+    if (fact === undefined) continue;
+    const remote = toRemote(fact);
+    ordered.push(sameRemote(prior, remote) ? prior : remote);
+  }
+  for (const fact of facts) {
+    if (!known.has(fact.identity)) ordered.push(toRemote(fact));
+  }
+  if (sameItems(previous, ordered)) return previous;
+  return ordered.length === 0 ? NO_REMOTES : ordered;
+}
+
+export function toLocal(facts: ParticipantFacts): LocalParticipant {
+  return {
+    kind: "local",
+    identity: toParticipantIdentity(facts.identity),
+    displayName: displayNameOf(facts),
+    microphone: { muted: facts.microphone.muted },
+    camera: { muted: facts.camera.muted },
+  };
+}
+
+export function toRemote(facts: ParticipantFacts): RemoteParticipant {
+  return {
+    kind: "remote",
+    identity: toParticipantIdentity(facts.identity),
+    displayName: displayNameOf(facts),
+    microphone: { muted: facts.microphone.muted, subscribed: facts.microphone.subscribed },
+    camera: { muted: facts.camera.muted, subscribed: facts.camera.subscribed },
+  };
+}
+
+/** The token name, or the identity when the name is missing or empty. */
+export function displayNameFrom(identity: string, name: string | undefined): string {
+  return name !== undefined && name !== "" ? name : identity;
+}
+
+function displayNameOf(facts: ParticipantFacts): string {
+  return displayNameFrom(facts.identity, facts.name);
+}
+
+function sameLocal(a: LocalParticipant, b: LocalParticipant): boolean {
+  return (
+    a.identity === b.identity &&
+    a.displayName === b.displayName &&
+    a.microphone.muted === b.microphone.muted &&
+    a.camera.muted === b.camera.muted
+  );
+}
+
+function sameRemote(a: RemoteParticipant, b: RemoteParticipant): boolean {
+  return (
+    a.identity === b.identity &&
+    a.displayName === b.displayName &&
+    a.microphone.muted === b.microphone.muted &&
+    a.microphone.subscribed === b.microphone.subscribed &&
+    a.camera.muted === b.camera.muted &&
+    a.camera.subscribed === b.camera.subscribed
+  );
+}
+
+/** Same length and the same entries by reference, in order. */
+export function sameItems<T>(a: readonly T[], b: readonly T[]): boolean {
+  return a.length === b.length && a.every((entry, index) => entry === b[index]);
+}
diff --git a/packages/realtime/src/realtime-room/domain/snapshot-mapping.ts b/packages/realtime/src/realtime-room/domain/snapshot-mapping.ts
new file mode 100644
index 00000000..264fc716
--- /dev/null
+++ b/packages/realtime/src/realtime-room/domain/snapshot-mapping.ts
@@ -0,0 +1,151 @@
+import type { DeviceState, RoomSnapshot } from "@know-meet/application";
+import {
+  type ActiveDevices,
+  type AudioPlayback,
+  type BackgroundEffectState,
+  type ChatMessage,
+  type ConferencingSupport,
+  type ConnectionState,
+  DEFAULT_ACTIVE_DEVICES,
+  isInRoom,
+  type MediaDevice,
+  NO_BACKGROUND_EFFECT_STATE,
+  NOTHING_SUPPORTED,
+  sameBackgroundEffect,
+} from "@know-meet/domain";
+import { IDLE, sameConnection } from "./connection-mapping.ts";
+import { NO_DEVICES, sameActiveDevices, sameDevices } from "./device-mapping.ts";
+import {
+  NO_REMOTES,
+  nextLocal,
+  nextRemotes,
+  type ParticipantFacts,
+} from "./participant-mapping.ts";
+import {
+  NO_SCREEN_SHARES,
+  nextScreenShares,
+  type ScreenShareFacts,
+} from "./screen-share-mapping.ts";
+
+export {
+  type ParticipantFacts,
+  type TrackFacts,
+  toLocal,
+  toRemote,
+  UNPUBLISHED,
+} from "./participant-mapping.ts";
+
+/**
+ * Everything a snapshot is built from at one moment: what the SDK reports (connection,
+ * participants, shares, playback, devices in use) and what the adapter itself holds (chat,
+ * the device list, the background effect, support).
+ */
+export interface RoomFacts {
+  readonly connection: ConnectionState;
+  readonly local: ParticipantFacts | null;
+  /** In the SDK's order, which is the order participants were added. */
+  readonly remotes: readonly ParticipantFacts[];
+  readonly screenShares: readonly ScreenShareFacts[];
+  readonly chat: readonly ChatMessage[];
+  readonly availableDevices: readonly MediaDevice[];
+  readonly activeDevices: ActiveDevices;
+  readonly audioPlayback: AudioPlayback;
+  readonly backgroundEffect: BackgroundEffectState;
+  readonly support: ConferencingSupport;
+}
+
+const NO_CHAT: readonly ChatMessage[] = [];
+
+/** The snapshot of a room that has never connected. */
+export function initialSnapshot(
+  support: ConferencingSupport,
+  available: readonly MediaDevice[] = NO_DEVICES,
+): RoomSnapshot {
+  return {
+    connection: IDLE,
+    local: null,
+    remotes: NO_REMOTES,
+    screenShares: NO_SCREEN_SHARES,
+    chat: NO_CHAT,
+    devices: { available, active: DEFAULT_ACTIVE_DEVICES },
+    audioPlayback: "allowed",
+    backgroundEffect: NO_BACKGROUND_EFFECT_STATE,
+    support,
+  };
+}
+
+export const INITIAL_SNAPSHOT: RoomSnapshot = initialSnapshot(NOTHING_SUPPORTED);
+
+/**
+ * The snapshot for `facts`, reusing every unchanged part of `previous`. Returns `previous`
+ * itself when nothing changed, so `useSyncExternalStore` sees a stable reference. Local and
+ * remote participants and screen shares exist only while the room is joined (connected or
+ * reconnecting).
+ */
+export function nextSnapshot(previous: RoomSnapshot, facts: RoomFacts): RoomSnapshot {
+  const connection = sameConnection(previous.connection, facts.connection)
+    ? previous.connection
+    : facts.connection;
+  const inRoom = isInRoom(connection);
+  const local = inRoom && facts.local !== null ? nextLocal(previous.local, facts.local) : null;
+  const remotes = nextRemotes(previous.remotes, inRoom ? facts.remotes : []);
+  const screenShares = nextScreenShares(
+    previous.screenShares,
+    inRoom ? facts.screenShares : [],
+    remotes,
+  );
+  const next: RoomSnapshot = {
+    connection,
+    local,
+    remotes,
+    screenShares,
+    chat: facts.chat.length === 0 ? NO_CHAT : facts.chat,
+    devices: nextDevices(previous.devices, facts),
+    audioPlayback: facts.audioPlayback,
+    backgroundEffect: nextEffect(previous.backgroundEffect, facts.backgroundEffect),
+    support: sameSupport(previous.support, facts.support) ? previous.support : facts.support,
+  };
+  return sameSnapshot(previous, next) ? previous : next;
+}
+
+function nextDevices(previous: DeviceState, facts: RoomFacts): DeviceState {
+  const available = sameDevices(previous.available, facts.availableDevices)
+    ? previous.available
+    : facts.availableDevices;
+  const active = sameActiveDevices(previous.active, facts.activeDevices)
+    ? previous.active
+    : facts.activeDevices;
+  if (available === previous.available && active === previous.active) return previous;
+  return { available, active };
+}
+
+function nextEffect(
+  previous: BackgroundEffectState,
+  next: BackgroundEffectState,
+): BackgroundEffectState {
+  const same =
+    previous.status === next.status && sameBackgroundEffect(previous.effect, next.effect);
+  return same ? previous : next;
+}
+
+function sameSupport(a: ConferencingSupport, b: ConferencingSupport): boolean {
+  return (
+    a.screenShare === b.screenShare &&
+    a.backgroundEffects === b.backgroundEffects &&
+    a.speakerSelection === b.speakerSelection
+  );
+}
+
+function sameSnapshot(a: RoomSnapshot, b: RoomSnapshot): boolean {
+  return (
+    a.connection === b.connection &&
+    a.local === b.local &&
+    a.remotes === b.remotes &&
+    a.screenShares === b.screenShares &&
+    a.chat === b.chat &&
+    a.devices === b.devices &&
+    a.audioPlayback === b.audioPlayback &&
+    a.backgroundEffect === b.backgroundEffect &&
+    a.support === b.support
+  );
+}
diff --git a/packages/realtime/src/realtime-room/index.ts b/packages/realtime/src/realtime-room/index.ts
new file mode 100644
index 00000000..477b2a33
--- /dev/null
+++ b/packages/realtime/src/realtime-room/index.ts
@@ -0,0 +1,17 @@
+/** The LiveKit realtime room feature: public surface only. */
+export type {
+  DiagnosticSink,
+  DropReason,
+  MessageChannel,
+  RealtimeDiagnostic,
+} from "./application/diagnostics.ts";
