--- /dev/null
+++ b/packages/realtime/src/realtime-room/infrastructure/livekit/audio-playback.ts
@@ -0,0 +1,43 @@
+import type { AudioStartError } from "@know-meet/application";
+import { conferencingErrors, err, meetingErrors, ok, type Result } from "@know-meet/domain";
+import type { Room } from "livekit-client";
+import type { SessionHost } from "./session-host.ts";
+
+export type StartAudio = () => Promise<Result<void, AudioStartError>>;
+
+/**
+ * The port's `startAudio` (WC-12), for the "Enable audio" click. The SDK call is made
+ * synchronously, before any await, so it runs inside the click's user activation. The
+ * snapshot's `audioPlayback` follows the SDK's `canPlaybackAudio`, which turns false when an
+ * attached element's `play()` is refused and true again once this succeeds.
+ */
+export function createStartAudio(host: SessionHost): StartAudio {
+  return async () => {
+    const active = host.joined();
+    if (active === null) return err(meetingErrors.connectionLost());
+    const started = active.room.startAudio();
+    try {
+      await started;
+    } catch {
+      // The SDK has already reported the failure through AudioPlaybackStatusChanged.
+      if (!host.isCurrent(active)) return err(meetingErrors.connectionLost());
+      host.refresh();
+      return err(conferencingErrors.playbackBlocked());
+    }
+    if (!host.isCurrent(active)) return err(meetingErrors.connectionLost());
+    host.refresh();
+    return active.room.canPlaybackAudio ? ok(undefined) : err(conferencingErrors.playbackBlocked());
+  };
+}
+
+/**
+ * Right after joining, which starts from a click: plays remote audio under that click's
+ * sticky activation. If the browser still blocks it, the snapshot shows `blocked` and the
+ * page offers "Enable audio".
+ */
+export function startAudioAfterJoin(room: Room, host: SessionHost): void {
+  void room.startAudio().catch(() => {
+    host.report({ type: "audio-playback", playing: false });
+    host.scheduleRefresh();
+  });
+}
diff --git a/packages/realtime/src/realtime-room/infrastructure/livekit/background-effect.ts b/packages/realtime/src/realtime-room/infrastructure/livekit/background-effect.ts
new file mode 100644
index 00000000..7210fe2f
--- /dev/null
+++ b/packages/realtime/src/realtime-room/infrastructure/livekit/background-effect.ts
@@ -0,0 +1,150 @@
+import type { BackgroundEffectError } from "@know-meet/application";
+import {
+  type BackgroundEffect,
+  type BackgroundEffectState,
+  type BackgroundEffectStatus,
+  type ConferencingSupport,
+  conferencingErrors,
+  err,
+  meetingErrors,
+  NO_BACKGROUND_EFFECT,
+  NO_BACKGROUND_EFFECT_STATE,
+  ok,
+  type Result,
+  sameBackgroundEffect,
+} from "@know-meet/domain";
+import { type LocalVideoTrack, type Room, Track } from "livekit-client";
+import { type CameraState, planBackgroundEffect } from "../../domain/background-effect-plan.ts";
+import { errorName } from "../../domain/error-mapping.ts";
+import type { SessionHost } from "./session-host.ts";
+import type { ProcessedBackgroundEffect, VideoProcessorHook } from "./video-processor-hook.ts";
+
+/** The background effect request and the controller that keeps it true (WC-4). */
+export interface BackgroundEffects {
+  state(): BackgroundEffectState;
+  /** Called by every refresh: looks at the camera track and starts the next step if one is due. */
+  reconcile(room: Room | null): void;
+  /** Forgets the request (a new connect, or leaving). */
+  reset(): void;
+  setBackgroundEffect(effect: BackgroundEffect): Promise<Result<void, BackgroundEffectError>>;
+}
+
+interface Applied {
+  readonly track: LocalVideoTrack;
+  readonly effect: ProcessedBackgroundEffect;
+}
+
+interface Camera {
+  readonly track: LocalVideoTrack | null;
+  readonly state: CameraState;
+}
+
+function readCamera(room: Room | null): Camera {
+  const publication = room?.localParticipant.getTrackPublication(Track.Source.Camera);
+  const track = publication?.videoTrack ?? null;
+  if (publication === undefined || track === null) return { track: null, state: "none" };
+  return { track, state: publication.isMuted ? "off" : "on" };
+}
+
+export function createBackgroundEffects(
+  host: SessionHost,
+  hook: VideoProcessorHook | undefined,
+  support: ConferencingSupport,
+): BackgroundEffects {
+  let requested: BackgroundEffect = NO_BACKGROUND_EFFECT;
+  let status: BackgroundEffectStatus = "idle";
+  let applied: Applied | null = null;
+  let failedTrack: LocalVideoTrack | null = null;
+  let busy: Promise<void> | null = null;
+  let generation = 0;
+
+  /** Runs one hook call; its outcome counts only if no reset happened meanwhile. */
+  const run = (call: () => Promise<void>, onDone: (succeeded: boolean) => void): void => {
+    const started = generation;
+    busy = call()
+      .then(
+        () => {
+          if (started === generation) onDone(true);
+        },
+        (error: unknown) => {
+          host.report({ type: "background-effect-failed", errorName: errorName(error) });
+          if (started === generation) onDone(false);
+        },
+      )
+      .finally(() => {
+        busy = null;
+        host.scheduleRefresh();
+      });
+  };
+
+  const reconcile = (room: Room | null): void => {
+    if (busy !== null || hook === undefined) return;
+    const camera = readCamera(room);
+    // A replaced track took its processor with it; one the SDK dropped is gone too.
+    const lost =
+      applied !== null &&
+      (applied.track !== camera.track || applied.track.getProcessor() === undefined);
+    if (lost) applied = null;
+    const plan = planBackgroundEffect({
+      requested,
+      camera: camera.state,
+      appliedHere: applied !== null && sameBackgroundEffect(applied.effect, requested),
+      processorHere: applied !== null,
+      failedHere: failedTrack !== null && failedTrack === camera.track,
+    });
+    status = plan.status;
+    const track = camera.track;
+    if (track === null) return;
+    if (plan.action === "remove") {
+      const removed = (): void => {
+        applied = null;
+      };
+      run(() => hook.remove(track), removed);
+    } else if (plan.action === "apply" && requested.kind !== "none") {
+      const effect = requested;
+      const done = (succeeded: boolean): void => {
+        if (succeeded) applied = { track, effect };
+        else failedTrack = track;
+      };
+      run(() => hook.apply(track, effect), done);
+    }
+  };
+
+  /** Waits until no hook call runs and the latest request needs no further step. */
+  const settle = async (): Promise<void> => {
+    while (busy !== null) {
+      await busy;
+      host.refresh();
+    }
+  };
+
+  return {
+    state: () =>
+      requested.kind === "none" && status === "idle"
+        ? NO_BACKGROUND_EFFECT_STATE
+        : { effect: requested, status },
+    reconcile,
+    reset: () => {
+      generation += 1;
+      requested = NO_BACKGROUND_EFFECT;
+      status = "idle";
+      applied = null;
+      failedTrack = null;
+    },
+    setBackgroundEffect: async (effect) => {
+      const active = host.joined();
+      if (active === null) return err(meetingErrors.connectionLost());
+      const unsupported = hook === undefined || support.backgroundEffects === "unsupported";
+      if (effect.kind !== "none" && unsupported) {
+        return err(conferencingErrors.unsupported("backgroundEffects"));
+      }
+      requested = effect;
+      failedTrack = null;
+      host.refresh();
+      await settle();
+      if (!host.isCurrent(active)) return err(meetingErrors.connectionLost());
+      const failed = status === "failed" && sameBackgroundEffect(requested, effect);
+      return failed ? err(conferencingErrors.effectFailed()) : ok(undefined);
+    },
+  };
+}
diff --git a/packages/realtime/src/realtime-room/infrastructure/livekit/background-processor-hook.ts b/packages/realtime/src/realtime-room/infrastructure/livekit/background-processor-hook.ts
new file mode 100644
index 00000000..675cc354
--- /dev/null
+++ b/packages/realtime/src/realtime-room/infrastructure/livekit/background-processor-hook.ts
@@ -0,0 +1,97 @@
+import type {
+  BackgroundProcessorWrapper,
+  SwitchBackgroundProcessorOptions,
+} from "@livekit/track-processors";
+import type { LocalVideoTrack } from "livekit-client";
+import type {
+  BackgroundAssetPaths,
+  ProcessedBackgroundEffect,
+  VideoProcessorHook,
+} from "./video-processor-hook.ts";
+
+type TrackProcessorsModule = typeof import("@livekit/track-processors");
+
+/** The effect as the processor's `switchTo` takes it. Blur keeps the library's default radius. */
+function toSwitchOptions(effect: ProcessedBackgroundEffect): SwitchBackgroundProcessorOptions {
+  if (effect.kind === "blur") return { mode: "background-blur" };
+  return { mode: "virtual-background", imagePath: effect.imageUrl };
+}
+
+/**
+ * The `VideoProcessorHook` over `@livekit/track-processors` 0.8.3 (WC-4).
+ *
+ * - **Lazy.** The library (and MediaPipe behind it) is imported on the first `apply`, not when
+ *   the hook is created, so a meeting without effects never downloads it.
+ * - **One processor per track, switched.** The first effect on a track constructs a
+ *   `BackgroundProcessor` in `disabled` mode (frames pass through unchanged, as the camera
+ *   already looks), sets it on the track, then `switchTo`s the effect. Later effects on the
+ *   same track only `switchTo`. Construction in `disabled` mode matters: the library only
+ *   logs a background image that fails to load during construction or `init`, but `switchTo`
+ *   rejects, so a missing preset image surfaces as a failure instead of a silent no-op.
+ * - **Failure leaves the camera unprocessed.** If loading the library, the WASM, the model or
+ *   the image rejects, the hook takes its processor off the track before rejecting, so the
+ *   adapter's `failed` status is true of what others receive.
+ *
+ * `paths` are the same-origin locations of the tasks-vision WASM file set and the pinned
+ * segmenter model. They go to every processor this hook constructs as `assetPaths`, so
+ * MediaPipe never falls back to its CDN defaults (`connect-src` would block them).
+ */
+export function createBackgroundProcessorHook(paths: BackgroundAssetPaths): VideoProcessorHook {
+  const assetPaths = {
+    tasksVisionFileSet: paths.tasksVisionFileSet,
+    modelAssetPath: paths.modelAssetPath,
+  };
+  const ours = new WeakSet<object>();
+  let loading: Promise<TrackProcessorsModule> | null = null;
+
+  /** Imports the library once; a failed import is forgotten so a later request can retry. */
+  const loadLibrary = (): Promise<TrackProcessorsModule> => {
+    loading ??= import("@livekit/track-processors").catch((error: unknown) => {
+      loading = null;
+      throw error;
+    });
+    return loading;
+  };
+
+  /** The processor this hook set on `track`, if it is still there. */
+  const processorOn = (track: LocalVideoTrack): BackgroundProcessorWrapper | null => {
+    const current = track.getProcessor();
+    return current !== undefined && isOurs(current) ? current : null;
+  };
+
+  /** Only processors this hook constructed are in `ours`, and each is a wrapper. */
+  const isOurs = (candidate: object): candidate is BackgroundProcessorWrapper =>
+    ours.has(candidate);
+
+  const attach = async (track: LocalVideoTrack): Promise<BackgroundProcessorWrapper> => {
+    const existing = processorOn(track);
+    if (existing !== null) return existing;
+    const library = await loadLibrary();
+    const processor = library.BackgroundProcessor({ mode: "disabled", assetPaths });
+    ours.add(processor);
+    // Rejects when the WASM file set or the model cannot load; the track keeps no processor.
+    await track.setProcessor(processor);
+    return processor;
+  };
+
+  const remove = async (track: LocalVideoTrack): Promise<void> => {
+    if (processorOn(track) === null) return;
+    await track.stopProcessor();
+  };
+
+  return {
+    apply: async (track, effect) => {
+      try {
+        const processor = await attach(track);
+        await processor.switchTo(toSwitchOptions(effect));
+      } catch (error: unknown) {
+        // The primary error is what the adapter reports. A failure to take the processor off
+        // again cannot be reported separately through this seam; the adapter's next refresh
+        // sees whatever processor is left and reconciles against it.
+        await remove(track).catch(() => undefined);
+        throw error;
+      }
+    },
+    remove,
+  };
+}
diff --git a/packages/realtime/src/realtime-room/infrastructure/livekit/connection-lifecycle.ts b/packages/realtime/src/realtime-room/infrastructure/livekit/connection-lifecycle.ts
new file mode 100644
index 00000000..134a3443
--- /dev/null
+++ b/packages/realtime/src/realtime-room/infrastructure/livekit/connection-lifecycle.ts
@@ -0,0 +1,131 @@
+import type { ConnectError, ConnectOptions, RoomCredentials } from "@know-meet/application";
+import { DEFAULT_DEVICE_CHOICE, err, meetingErrors, ok, type Result } from "@know-meet/domain";
+import { ConnectionErrorReason, Room, type RoomOptions } from "livekit-client";
+import {
+  CONNECTED,
+  CONNECTING,
+  CONNECTION_LOST,
+  IDLE,
+  LEFT,
+  toLiveConnection,
+} from "../../domain/connection-mapping.ts";
+import { errorName, isTokenRejection, mapConnectError } from "../../domain/error-mapping.ts";
+import { startAudioAfterJoin } from "./audio-playback.ts";
+import { bindRoomEvents, type RoomEventHandlers } from "./room-events.ts";
+import type { Session, SessionHost } from "./session-host.ts";
+
+/** `ConnectionErrorReason.NotAllowed`: the server refused the token. */
+const TOKEN_REFUSED: number = ConnectionErrorReason.NotAllowed;
+
+/** What the features do at the edges of a session. */
+export interface SessionFeatures {
+  /** Room options for this connect, with the lobby's device choice applied. */
+  roomOptionsFor(options: ConnectOptions): RoomOptions;
+  /** The SDK room exists and is about to connect: register stream handlers. */
+  onSessionStart(session: Session): void;
+  /** A new connect begins, or the guest left: clear per-session state (chat, effect). */
+  onSessionReset(): void;
+}
+
+export interface ConnectionLifecycle {
+  connect(
+    credentials: RoomCredentials,
+    options?: ConnectOptions,
+  ): Promise<Result<void, ConnectError>>;
+  disconnect(): Promise<void>;
+}
+
+/**
+ * Connect and disconnect. It opens no connection until `connect`, so a refused token request
+ * never reaches the media server, and it tries once: a refused token is not retried, and
+ * neither is an unreachable server.
+ */
+export function createConnectionLifecycle(
+  host: SessionHost,
+  features: SessionFeatures,
+): ConnectionLifecycle {
+  let pendingConnect: number | null = null;
+
+  /** The SDK gave up reconnecting, or the server ended the session. The guest did not leave. */
+  const onSessionEnded = (id: number): void => {
+    const lost = host.session();
+    if (lost === null || !host.isCurrent({ id }) || pendingConnect === id) return;
+    host.setSession(null);
+    host.setConnection(CONNECTION_LOST);
+    void host.release(lost);
+  };
+
+  const handlersFor = (id: number): RoomEventHandlers => ({
+    onChange: () => {
+      if (host.isCurrent({ id })) host.scheduleRefresh();
+    },
+    onConnectionState: (sdkState) => {
+      const next = toLiveConnection(sdkState);
+      if (next !== null && host.isCurrent({ id })) host.setConnection(next);
+    },
+    onDisconnected: () => onSessionEnded(id),
+    onAudioPlayback: (playing) => {
+      host.report({ type: "audio-playback", playing });
+      if (host.isCurrent({ id })) host.scheduleRefresh();
+    },
+  });
+
+  const attempt = async (
+    room: Room,
+    credentials: RoomCredentials,
+  ): Promise<Result<void, unknown>> => {
+    try {
+      await room.connect(credentials.url, credentials.token);
+      return ok(undefined);
+    } catch (error) {
+      return err(error);
+    }
+  };
+
+  const failConnect = async (error: unknown): Promise<Result<void, ConnectError>> => {
+    const tokenRejected = isTokenRejection(error, TOKEN_REFUSED);
+    host.report({ type: "connect-failed", errorName: errorName(error), tokenRejected });
+    const failed = host.session();
+    host.setSession(null);
+    host.setConnection(IDLE);
+    if (failed !== null) await host.release(failed);
+    return err(mapConnectError(error, TOKEN_REFUSED));
+  };
+
+  const connect = async (
+    credentials: RoomCredentials,
+    options?: ConnectOptions,
+  ): Promise<Result<void, ConnectError>> => {
+    const previous = host.session();
+    if (previous !== null) {
+      host.setSession(null);
+      await host.release(previous);
+    }
+    features.onSessionReset();
+    const id = host.nextSessionId();
+    const room = new Room(features.roomOptionsFor(options ?? { devices: DEFAULT_DEVICE_CHOICE }));
+    const session: Session = { id, room, unbind: bindRoomEvents(room, handlersFor(id)) };
+    host.setSession(session);
+    features.onSessionStart(session);
+    pendingConnect = id;
+    host.setConnection(CONNECTING);
+    const outcome = await attempt(room, credentials);
+    if (pendingConnect === id) pendingConnect = null;
+    // `disconnect` ran while connecting: it already tore the room down and reported `left`.
+    if (!host.isCurrent(session)) return err(meetingErrors.connectionLost());
+    if (!outcome.ok) return failConnect(outcome.error);
+    host.setConnection(CONNECTED);
+    startAudioAfterJoin(room, host);
+    return ok(undefined);
+  };
+
+  const disconnect = async (): Promise<void> => {
+    const ending = host.session();
+    host.setSession(null);
+    if (ending !== null) await host.release(ending);
+    features.onSessionReset();
+    host.setConnection(LEFT);
+  };
+
+  return { connect, disconnect };
+}
diff --git a/packages/realtime/src/realtime-room/infrastructure/livekit/create-livekit-realtime-room.ts b/packages/realtime/src/realtime-room/infrastructure/livekit/create-livekit-realtime-room.ts
new file mode 100644
index 00000000..69f51b96
--- /dev/null
+++ b/packages/realtime/src/realtime-room/infrastructure/livekit/create-livekit-realtime-room.ts
@@ -0,0 +1,107 @@
+import type { MediaTarget, RealtimeRoom } from "@know-meet/application";
+import type { ConnectionState } from "@know-meet/domain";
+import type { Room, RoomOptions } from "livekit-client";
+import { type DiagnosticSink, ignoreDiagnostic } from "../../application/diagnostics.ts";
+import { createMediaBindings } from "../../application/media-bindings.ts";
+import { createSnapshotStore } from "../../application/snapshot-store.ts";
+import { initialSnapshot } from "../../domain/snapshot-mapping.ts";
+import { detectConferencingSupport } from "../browser/conferencing-support.ts";
+import { getDeviceCatalog } from "../browser/device-catalog.ts";
+import { createStartAudio } from "./audio-playback.ts";
+import { createBackgroundEffects } from "./background-effect.ts";
+import { createConnectionLifecycle } from "./connection-lifecycle.ts";
+import { createDevices } from "./devices.ts";
+import { createSetMediaEnabled } from "./media-control.ts";
+import { readRoomFacts } from "./room-facts.ts";
+import { createSetScreenShareEnabled } from "./screen-share.ts";
+import { createSessionHost } from "./session-host.ts";
+import { createTextStreams } from "./text-streams.ts";
+import { createTrackResolver } from "./track-resolver.ts";
+import type { VideoProcessorHook } from "./video-processor-hook.ts";
+
+export interface LiveKitRealtimeRoomOptions {
+  /**
+   * Let the SDK pause remote video whose element is hidden or small. Off by default: a
+   * two-person call gains little, and a hidden or background tab would stop video (README).
+   */
+  readonly adaptiveStream?: boolean;
+  /** Let the publisher pause simulcast layers nobody watches. On by default. */
+  readonly dynacast?: boolean;
+  /** Receives connection, failure and audio-playback events. Never receives a token. */
+  readonly onDiagnostic?: DiagnosticSink;
+  /**
+   * The background processor (wc07). Without it `support.backgroundEffects` is unsupported
+   * and only `none` is accepted. The lazy room must be told the same (`backgroundEffects`).
+   */
+  readonly videoProcessor?: VideoProcessorHook;
+}
+
+/**
+ * The RealtimeRoom port over livekit-client. Nothing it returns names an SDK type. It opens
+ * no connection until `connect`, so a refused token request never reaches the media server.
+ * Device list and support are current from creation, before any connect.
+ */
+export function createLiveKitRealtimeRoom(options: LiveKitRealtimeRoomOptions = {}): RealtimeRoom {
+  const report = options.onDiagnostic ?? ignoreDiagnostic;
+  const baseRoomOptions: RoomOptions = {
+    adaptiveStream: options.adaptiveStream ?? false,
+    dynacast: options.dynacast ?? true,
+    webAudioMix: false,
+  };
+  const support = detectConferencingSupport({
+    backgroundEffects: options.videoProcessor !== undefined,
+  });
+  const catalog = getDeviceCatalog();
+  const store = createSnapshotStore(initialSnapshot(support, catalog.current()));
+  const bindings = createMediaBindings();
+
+  /**
+   * Re-reads the SDK, publishes a new snapshot if anything changed, and re-binds media. Runs
+   * only from `host.refresh`, which nothing calls before the features below exist.
+   */
+  const onRefresh = (room: Room | null, connection: ConnectionState): void => {
+    effects.reconcile(room);
+    store.update({
+      ...readRoomFacts(room, connection, devices.requested()),
+      chat: text.chat(),
+      availableDevices: catalog.current(),
+      backgroundEffect: effects.state(),
+      support,
+    });
+    bindings.reconcile(createTrackResolver(room));
+  };
+
+  const host = createSessionHost(report, onRefresh);
+  const devices = createDevices(host, catalog, support);
+  const text = createTextStreams(host);
+  const effects = createBackgroundEffects(host, options.videoProcessor, support);
+  const lifecycle = createConnectionLifecycle(host, {
+    roomOptionsFor: (connectOptions) =>
+      devices.roomOptionsFor(baseRoomOptions, connectOptions.devices),
+    onSessionStart: (session) => text.attach(session),
+    onSessionReset: () => {
+      text.reset();
+      effects.reset();
+    },
+  });
+  // Page lifetime, like the catalog itself: the lobby lists devices before any connect.
+  catalog.subscribe(() => host.refresh());
+
+  return {
+    connect: lifecycle.connect,
+    disconnect: lifecycle.disconnect,
+    setMediaEnabled: createSetMediaEnabled(host, catalog, () => devices.requested()),
+    getSnapshot: store.get,
+    subscribe: store.subscribe,
+    attachMedia: (target: MediaTarget, element: HTMLMediaElement) =>
+      bindings.bind(target, element, createTrackResolver(host.session()?.room ?? null)),
+    setScreenShareEnabled: createSetScreenShareEnabled(host, support),
+    sendChat: text.sendChat,
+    refreshDevices: devices.refreshDevices,
+    selectDevice: devices.selectDevice,
+    startAudio: createStartAudio(host),
+    setBackgroundEffect: effects.setBackgroundEffect,
+    sendConsentMessage: text.sendConsentMessage,
+    onConsentMessage: text.onConsentMessage,
+  };
+}
diff --git a/packages/realtime/src/realtime-room/infrastructure/livekit/devices.ts b/packages/realtime/src/realtime-room/infrastructure/livekit/devices.ts
new file mode 100644
index 00000000..cdd8e093
--- /dev/null
+++ b/packages/realtime/src/realtime-room/infrastructure/livekit/devices.ts
@@ -0,0 +1,98 @@
+import type { DeviceError } from "@know-meet/application";
+import {
+  type ActiveDevices,
+  type ConferencingSupport,
+  conferencingErrors,
+  DEFAULT_ACTIVE_DEVICES,
+  type DeviceChoice,
+  type DeviceId,
+  type DeviceKind,
+  err,
+  hasDevice,
+  meetingErrors,
+  ok,
+  type Result,
+} from "@know-meet/domain";
+import type { RoomOptions } from "livekit-client";
+import { browserKindOf, requestedFromChoice } from "../../domain/device-mapping.ts";
+import { errorName, mapDeviceSwitchError } from "../../domain/error-mapping.ts";
+import type { DeviceCatalog } from "../browser/device-catalog.ts";
+import type { SessionHost } from "./session-host.ts";
+
+/** Device choice and switching (WC-5, WC-6). The list itself comes from the page's catalog. */
+export interface Devices {
+  /** What was asked for: the lobby choice, then each `selectDevice`. */
+  requested(): ActiveDevices;
+  /**
+   * Room options for a new session with the lobby's choice as capture defaults. The id is
+   * `ideal`, not `exact`: a device unplugged since the lobby falls back to the system default
+   * instead of failing (port contract), and the SDK reports the device it actually opened.
+   */
+  roomOptionsFor(base: RoomOptions, choice: DeviceChoice): RoomOptions;
+  refreshDevices(): Promise<void>;
+  selectDevice(kind: DeviceKind, id: DeviceId): Promise<Result<void, DeviceError>>;
+}
+
+export function createDevices(
+  host: SessionHost,
+  catalog: DeviceCatalog,
+  support: ConferencingSupport,
+): Devices {
+  let requested: ActiveDevices = DEFAULT_ACTIVE_DEVICES;
+
+  const roomOptionsFor = (base: RoomOptions, choice: DeviceChoice): RoomOptions => {
+    requested = requestedFromChoice(choice, requested);
+    return {
+      ...base,
+      ...(choice.microphone !== null
+        ? { audioCaptureDefaults: { deviceId: { ideal: choice.microphone } } }
+        : {}),
+      ...(choice.camera !== null
+        ? { videoCaptureDefaults: { deviceId: { ideal: choice.camera } } }
+        : {}),
+      ...(requested.speaker !== null ? { audioOutput: { deviceId: requested.speaker } } : {}),
+    };
+  };
+
+  /**
+   * Speaker selection is never attempted without support (the SDK throws there). A listed
+   * input is opened `exact`, so a device unplugged since the list was read fails as
+   * device-not-found rather than silently using another one. With the device off, the switch
+   * only changes what the next enable opens; with it on, the published track continues on the
+   * new device and keeps its processor (the SDK restarts both in place).
+   */
+  const selectDevice = async (
+    kind: DeviceKind,
+    id: DeviceId,
+  ): Promise<Result<void, DeviceError>> => {
+    const active = host.joined();
+    if (active === null) return err(meetingErrors.connectionLost());
+    if (kind === "speaker" && support.speakerSelection === "unsupported") {
+      return err(conferencingErrors.unsupported("speakerSelection"));
+    }
+    if (!hasDevice(catalog.current(), kind, id)) {
+      return err(conferencingErrors.deviceNotFound(kind));
+    }
+    try {
+      // The boolean it resolves with compares the requested id with the opened track's id,
+      // which differs for Chromium's "default" alias even on success, so only a throw fails.
+      await active.room.switchActiveDevice(browserKindOf(kind), id, true);
+    } catch (error) {
+      host.report({ type: "device-switch-failed", kind, errorName: errorName(error) });
+      if (!host.isCurrent(active)) return err(meetingErrors.connectionLost());
+      host.refresh();
+      return err(mapDeviceSwitchError(error, kind));
+    }
+    if (!host.isCurrent(active)) return err(meetingErrors.connectionLost());
+    requested = { ...requested, [kind]: id };
+    host.refresh();
+    return ok(undefined);
+  };
+
+  return {
+    requested: () => requested,
+    roomOptionsFor,
+    refreshDevices: () => catalog.refresh(),
+    selectDevice,
+  };
+}
diff --git a/packages/realtime/src/realtime-room/infrastructure/livekit/media-control.ts b/packages/realtime/src/realtime-room/infrastructure/livekit/media-control.ts
new file mode 100644
index 00000000..10e82dbf
--- /dev/null
+++ b/packages/realtime/src/realtime-room/infrastructure/livekit/media-control.ts
@@ -0,0 +1,97 @@
+import type { MediaError } from "@know-meet/application";
+import {
+  type ActiveDevices,
+  err,
+  meetingErrors,
+  ok,
+  type Result,
+  type TrackKind,
+} from "@know-meet/domain";
+import { type Room, Track } from "livekit-client";
+import { browserKindOf } from "../../domain/device-mapping.ts";
+import { errorName, mapMediaError } from "../../domain/error-mapping.ts";
+import type { DeviceCatalog } from "../browser/device-catalog.ts";
+import type { SessionHost } from "./session-host.ts";
+
+/**
+ * Turns the local microphone or camera on or off. The first enable asks the browser for the
+ * device and publishes the track; later calls mute or unmute it. A refused device rejects with
+ * the getUserMedia error (for example `NotAllowedError`) and leaves the room connected.
+ * Muting the camera stops the device, so the camera light goes off; muting the microphone
+ * keeps the device open (SDK default `stopMicTrackOnMute: false`). The device used is the
+ * room's capture default (the lobby choice) or the one `selectDevice` switched to.
+ */
+export async function setLocalMediaEnabled(
+  room: Room,
+  kind: TrackKind,
+  enabled: boolean,
+): Promise<void> {
+  if (kind === "microphone") {
+    await room.localParticipant.setMicrophoneEnabled(enabled);
+    return;
+  }
+  await room.localParticipant.setCameraEnabled(enabled);
+}
+
+/** The deviceId the published microphone or camera track actually opened, or null. */
+function openedDeviceId(room: Room, kind: TrackKind): string | null {
+  const source = kind === "microphone" ? Track.Source.Microphone : Track.Source.Camera;
+  const track = room.localParticipant.getTrackPublication(source)?.track;
+  return track?.mediaStreamTrack.getSettings().deviceId ?? null;
+}
+
+/**
+ * WC-5: the capture default asks for the lobby choice as `ideal`, and Chromium can open its
+ * "default" audio alias instead. When the opened device is not the requested one, switch to
+ * the requested id `exact` (the call `selectDevice` uses). A failed switch keeps the device
+ * that opened and is reported; the enable itself still succeeded.
+ */
+async function enforceRequestedDevice(
+  room: Room,
+  kind: TrackKind,
+  wanted: string | null,
+): Promise<void> {
+  if (wanted === null) return;
+  const opened = openedDeviceId(room, kind);
+  if (opened === null || opened === wanted) return;
+  await room.switchActiveDevice(browserKindOf(kind), wanted, true);
+}
+
+export type SetMediaEnabled = (
+  kind: TrackKind,
+  enabled: boolean,
+) => Promise<Result<void, MediaError>>;
+
+/**
+ * The port's `setMediaEnabled`. After a successful enable the device list is read again,
+ * because the browser reveals device labels once the site has permission.
+ */
+export function createSetMediaEnabled(
+  host: SessionHost,
+  catalog: DeviceCatalog,
+  requested: () => ActiveDevices,
+): SetMediaEnabled {
+  return async (kind, enabled) => {
+    const active = host.joined();
+    if (active === null) return err(meetingErrors.connectionLost());
+    try {
+      await setLocalMediaEnabled(active.room, kind, enabled);
+    } catch (error) {
+      host.report({ type: "media-failed", kind, errorName: errorName(error) });
+      if (host.isCurrent(active)) host.refresh();
+      return err(mapMediaError(error, kind));
+    }
+    if (!host.isCurrent(active)) return err(meetingErrors.connectionLost());
+    if (enabled) {
+      try {
+        await enforceRequestedDevice(active.room, kind, requested()[kind]);
+      } catch (error) {
+        host.report({ type: "device-switch-failed", kind, errorName: errorName(error) });
+      }
+      if (!host.isCurrent(active)) return err(meetingErrors.connectionLost());
+    }
+    host.refresh();
+    if (enabled) void catalog.refresh();
+    return ok(undefined);
+  };
+}
diff --git a/packages/realtime/src/realtime-room/infrastructure/livekit/room-events.ts b/packages/realtime/src/realtime-room/infrastructure/livekit/room-events.ts
new file mode 100644
index 00000000..4776b93a
--- /dev/null
+++ b/packages/realtime/src/realtime-room/infrastructure/livekit/room-events.ts
@@ -0,0 +1,47 @@
+import { type Room, RoomEvent } from "livekit-client";
+
+export interface RoomEventHandlers {
+  /** Participants, publications, subscriptions, mute state or devices in use changed. */
+  readonly onChange: () => void;
+  /** The SDK's connection state as its string value, e.g. `reconnecting`. */
+  readonly onConnectionState: (sdkState: string) => void;
+  /** The SDK ended the session (it emits this after its own teardown). */
+  readonly onDisconnected: () => void;
+  readonly onAudioPlayback: (playing: boolean) => void;
+}
+
+/** Room events that only mean "read the room again". */
+const CHANGE_EVENTS = [
+  RoomEvent.ParticipantConnected,
+  RoomEvent.ParticipantDisconnected,
+  RoomEvent.ParticipantNameChanged,
+  RoomEvent.TrackPublished,
+  RoomEvent.TrackUnpublished,
+  RoomEvent.TrackSubscribed,
+  RoomEvent.TrackUnsubscribed,
+  RoomEvent.TrackSubscriptionStatusChanged,
+  RoomEvent.TrackMuted,
+  RoomEvent.TrackUnmuted,
+  // Local publish and unpublish, including a screen share the browser's own "Stop sharing"
+  // bar ended: the SDK unpublishes a screen-share track when it ends.
+  RoomEvent.LocalTrackPublished,
+  RoomEvent.LocalTrackUnpublished,
+  // A device switched (by us or by the SDK after the chosen device was unplugged).
+  RoomEvent.ActiveDeviceChanged,
+  RoomEvent.MediaDevicesChanged,
+] as const;
+
+/** Registers the handlers on `room` and returns the function that removes every one of them. */
+export function bindRoomEvents(room: Room, handlers: RoomEventHandlers): () => void {
+  const { onChange, onConnectionState, onDisconnected, onAudioPlayback } = handlers;
+  room.on(RoomEvent.ConnectionStateChanged, onConnectionState);
+  room.on(RoomEvent.Disconnected, onDisconnected);
+  room.on(RoomEvent.AudioPlaybackStatusChanged, onAudioPlayback);
+  for (const event of CHANGE_EVENTS) room.on(event, onChange);
+  return () => {
+    room.off(RoomEvent.ConnectionStateChanged, onConnectionState);
+    room.off(RoomEvent.Disconnected, onDisconnected);
+    room.off(RoomEvent.AudioPlaybackStatusChanged, onAudioPlayback);
+    for (const event of CHANGE_EVENTS) room.off(event, onChange);
+  };
+}
diff --git a/packages/realtime/src/realtime-room/infrastructure/livekit/room-facts.ts b/packages/realtime/src/realtime-room/infrastructure/livekit/room-facts.ts
new file mode 100644
index 00000000..b534af30
--- /dev/null
+++ b/packages/realtime/src/realtime-room/infrastructure/livekit/room-facts.ts
@@ -0,0 +1,83 @@
+import type { ActiveDevices, ConnectionState } from "@know-meet/domain";
+import { type Participant, type Room, Track } from "livekit-client";
+import { activeDevicesFrom } from "../../domain/device-mapping.ts";
+import type { ScreenShareFacts } from "../../domain/screen-share-mapping.ts";
+import {
+  type ParticipantFacts,
+  type RoomFacts,
+  type TrackFacts,
+  UNPUBLISHED,
+} from "../../domain/snapshot-mapping.ts";
+
+/** The part of the facts the SDK room reports. */
+export type SdkFacts = Pick<
+  RoomFacts,
+  "connection" | "local" | "remotes" | "screenShares" | "audioPlayback" | "activeDevices"
+>;
+
+/**
+ * Reads the SDK room into plain facts. `room` is null before connecting and after leaving;
+ * `requested` is what was asked for, used where the SDK reports no device in use yet.
+ */
+export function readRoomFacts(
+  room: Room | null,
+  connection: ConnectionState,
+  requested: ActiveDevices,
+): SdkFacts {
+  if (room === null) {
+    return {
+      connection,
+      local: null,
+      remotes: [],
+      screenShares: [],
+      audioPlayback: "allowed",
+      activeDevices: requested,
+    };
+  }
+  // `remoteParticipants` is a Map keyed by identity; its iteration order is insertion order.
+  const remotes = [...room.remoteParticipants.values()];
+  return {
+    connection,
+    local: readParticipant(room.localParticipant),
+    remotes: remotes.map(readParticipant),
+    screenShares: [room.localParticipant, ...remotes].flatMap(readScreenShare),
+    audioPlayback: room.canPlaybackAudio ? "allowed" : "blocked",
+    activeDevices: activeDevicesFrom((kind) => room.getActiveDevice(kind), requested),
+  };
+}
+
+function readParticipant(participant: Participant): ParticipantFacts {
+  return {
+    identity: participant.identity,
+    name: participant.name,
+    microphone: readTrack(participant, Track.Source.Microphone),
+    camera: readTrack(participant, Track.Source.Camera),
+  };
+}
+
+function readTrack(participant: Participant, source: Track.Source): TrackFacts {
+  const publication = participant.getTrackPublication(source);
+  if (publication === undefined) return UNPUBLISHED;
+  // Remote publications override `isSubscribed` (false while unsubscribed or not allowed).
+  return { muted: publication.isMuted, subscribed: publication.isSubscribed };
+}
+
+/**
+ * The participant's screen share, if one is published. The local share counts once its
+ * track exists (it is never "subscribed" to itself); a remote one is subscribed when this
+ * client receives it.
+ */
+function readScreenShare(participant: Participant): ScreenShareFacts[] {
+  const video = participant.getTrackPublication(Track.Source.ScreenShare);
+  if (video === undefined) return [];
+  const isLocal = participant.isLocal;
+  if (isLocal && video.track === undefined) return [];
+  return [
+    {
+      identity: participant.identity,
+      isLocal,
+      subscribed: isLocal || video.isSubscribed,
+      hasAudio: participant.getTrackPublication(Track.Source.ScreenShareAudio) !== undefined,
+    },
+  ];
+}
diff --git a/packages/realtime/src/realtime-room/infrastructure/livekit/session-host.ts b/packages/realtime/src/realtime-room/infrastructure/livekit/session-host.ts
new file mode 100644
index 00000000..f6cc68b8
--- /dev/null
+++ b/packages/realtime/src/realtime-room/infrastructure/livekit/session-host.ts
@@ -0,0 +1,94 @@
+import { type ConnectionState, isInRoom } from "@know-meet/domain";
+import type { Room } from "livekit-client";
+import type { DiagnosticSink } from "../../application/diagnostics.ts";
+import { IDLE, sameConnection } from "../../domain/connection-mapping.ts";
+import { errorName } from "../../domain/error-mapping.ts";
+
+/** One SDK room from `connect` until it is left or lost. A new `connect` makes a new one. */
+export interface Session {
+  readonly id: number;
+  readonly room: Room;
+  readonly unbind: () => void;
+}
+
+/**
+ * The adapter's shared state: the current session and connection, and the refresh that turns
+ * them into a snapshot. Every feature reads the session through it, so a feature acting on a
+ * session that has since ended can tell (`isCurrent`).
+ */
+export interface SessionHost {
+  readonly report: DiagnosticSink;
+  session(): Session | null;
+  connection(): ConnectionState;
+  /** The session while joined (connected or reconnecting); room actions need it. */
+  joined(): Session | null;
+  /** The session while connected; sends need a live link, not a reconnecting one. */
+  live(): Session | null;
+  /** True while `candidate` (a session, or just its id) is still the current session. */
+  isCurrent(candidate: { readonly id: number }): boolean;
+  /** Re-reads the SDK now and publishes a new snapshot if anything changed. */
+  refresh(): void;
+  /** Refreshes one microtask later, batched (see `scheduleRefresh` below). */
+  scheduleRefresh(): void;
+  setSession(next: Session | null): void;
+  setConnection(next: ConnectionState): void;
+  nextSessionId(): number;
+  /** Removes our listeners, then disposes the room: disconnect, stop local tracks, drop globals. */
+  release(ended: Session): Promise<void>;
+}
+
+/** Called by every refresh with the current room (null when there is none). */
+export type RefreshHandler = (room: Room | null, connection: ConnectionState) => void;
+
+export function createSessionHost(report: DiagnosticSink, onRefresh: RefreshHandler): SessionHost {
+  let session: Session | null = null;
+  let connection: ConnectionState = IDLE;
+  let sessionCount = 0;
+  let refreshQueued = false;
+
+  const refresh = (): void => onRefresh(session?.room ?? null, connection);
+
+  return {
+    report,
+    session: () => session,
+    connection: () => connection,
+    joined: () => (session !== null && isInRoom(connection) ? session : null),
+    live: () => (session !== null && connection.status === "connected" ? session : null),
+    isCurrent: (candidate) => session !== null && session.id === candidate.id,
+    refresh,
+    /**
+     * SDK events fire mid-update (for example `TrackUnsubscribed` before the publication drops
+     * its track), so changes are read one microtask later, batched.
+     */
+    scheduleRefresh: () => {
+      if (refreshQueued) return;
+      refreshQueued = true;
+      queueMicrotask(() => {
+        refreshQueued = false;
+        refresh();
+      });
+    },
+    setSession: (next) => {
+      session = next;
+    },
+    setConnection: (next) => {
+      if (!sameConnection(connection, next)) {
+        report({ type: "connection-changed", connection: next });
+      }
+      connection = next;
+      refresh();
+    },
+    nextSessionId: () => {
+      sessionCount += 1;
+      return sessionCount;
+    },
+    release: async (ended) => {
+      ended.unbind();
+      try {
+        await ended.room.dispose();
+      } catch (error) {
+        report({ type: "teardown-failed", errorName: errorName(error) });
+      }
+    },
+  };
+}
diff --git a/packages/realtime/src/realtime-room/infrastructure/livekit/track-resolver.ts b/packages/realtime/src/realtime-room/infrastructure/livekit/track-resolver.ts
new file mode 100644
index 00000000..1cfd8bab
--- /dev/null
+++ b/packages/realtime/src/realtime-room/infrastructure/livekit/track-resolver.ts
@@ -0,0 +1,42 @@
+import type { MediaTarget } from "@know-meet/application";
+import type { MediaSource } from "@know-meet/domain";
+import { type Room, Track } from "livekit-client";
+import type { AttachableTrack, TrackResolver } from "../../application/media-bindings.ts";
+
+/**
+ * Which SDK track a target plays in `room` right now.
+ * - Local camera and local screen share: the published track (the camera is kept while
+ *   muted; the SDK restarts it in place).
+ * - Local microphone and local screen-share audio: never, so a participant does not hear
+ *   themselves.
+ * - Remote media of any source: the track only while subscribed.
+ */
+export function createTrackResolver(room: Room | null): TrackResolver {
+  return (target) => {
+    if (room === null) return null;
+    if (target.identity === room.localParticipant.identity) return localTrack(room, target);
+    const publication = room.remoteParticipants
+      .get(target.identity)
+      ?.getTrackPublication(sourceOf(target.kind));
+    if (publication === undefined || !publication.isSubscribed) return null;
+    return publication.track ?? null;
+  };
+}
+
+function localTrack(room: Room, target: MediaTarget): AttachableTrack | null {
+  if (target.kind === "microphone" || target.kind === "screen-share-audio") return null;
+  return room.localParticipant.getTrackPublication(sourceOf(target.kind))?.track ?? null;
+}
+
+export function sourceOf(kind: MediaSource): Track.Source {
+  switch (kind) {
+    case "camera":
+      return Track.Source.Camera;
+    case "microphone":
+      return Track.Source.Microphone;
+    case "screen-share":
+      return Track.Source.ScreenShare;
+    case "screen-share-audio":
+      return Track.Source.ScreenShareAudio;
+  }
+}
